.mb { --mb-ink: #1C2B24; --mb-muted: #5E6B64; --mb-line: #E3E8E5; --mb-accent: #136B43; --mb-tint: #EEF5F1; color: var(--mb-ink); line-height: 1.8; }
    .mb h2 { font-size: 19px; margin: 30px 0 4px; color: var(--mb-ink); }
    .mb .mb-why { color: var(--mb-muted); font-size: 14px; margin: 0 0 12px; }
    .mb .mb-high { background: var(--mb-tint); border-radius: 16px; padding: 14px 18px; margin: 8px 0 4px; }
    .mb .mb-high li { margin: 4px 0; font-weight: 600; }
    .mb .mb-note { border-inline-start: 4px solid var(--mb-accent); padding: 8px 14px; margin: 16px 0; background: #FAFBFA; white-space: pre-line; }
    .mb .mb-wrap { overflow-x: auto; }
    .mb table { width: 100%; border-collapse: collapse; font-size: 13.5px; }
    .mb th, .mb td { border-bottom: 1px solid var(--mb-line); padding: 7px 6px; text-align: start; vertical-align: middle; white-space: nowrap; }
    .mb th { color: var(--mb-muted); font-weight: 600; font-size: 12.5px; }
    .mb .mb-bar { display: inline-block; height: 9px; border-radius: 5px; background: var(--mb-accent); vertical-align: middle; margin-inline-start: 8px; }
    .mb .mb-empty { color: var(--mb-muted); font-size: 14px; }
    .mb .mb-method { color: var(--mb-muted); font-size: 12.5px; margin-top: 32px; border-top: 1px solid var(--mb-line); padding-top: 14px; }
    @media print { .mb h2 { break-after: avoid; } .mb table { break-inside: auto; } .mb tr { break-inside: avoid; } }
    .mb .mb-w0 { width: 2px; } .mb .mb-w1 { width: 9px; } .mb .mb-w2 { width: 18px; } .mb .mb-w3 { width: 27px; } .mb .mb-w4 { width: 36px; } .mb .mb-w5 { width: 45px; }
    .mb .mb-w6 { width: 54px; } .mb .mb-w7 { width: 63px; } .mb .mb-w8 { width: 72px; } .mb .mb-w9 { width: 81px; } .mb .mb-w10 { width: 90px; }
